#!/usr/bin/env bash
set -euo pipefail
python3 - <<'NOOK_UPDATE_PY'
from pathlib import Path
from datetime import datetime
import base64,io,tarfile,shutil,re,tempfile
root=Path('/addons'); target=root/'nook_casa'
if not (target/'config.yaml').is_file():
    raise SystemExit('Nook Casa non trovato: aggiornamento annullato.')
backup=Path('/config')/('nook_casa_backup_'+datetime.now().strftime('%Y%m%d_%H%M%S_%f'))
shutil.copytree(target,backup)
old=(target/'config.yaml').read_text()
if not re.search(r'^version:',old,re.M):raise SystemExit('Versione config non trovata')
new=re.sub(r'^version:.*$', 'version: "0.4.3"',old,count=1,flags=re.M)
new=re.sub(r'^description:.*$', 'description: Pannello Nook con comandi ACS e Holiday',new,count=1,flags=re.M)
raw=base64.b64decode('')
with tarfile.open(fileobj=io.BytesIO(raw),mode='r:gz') as archive:
    for member in archive.getmembers():
        if not member.isfile() or not member.name.startswith('nook_casa/') or '..' in Path(member.name).parts:
            raise SystemExit('Archivio non valido')
        if member.name.endswith('/config.yaml'):continue
        path=root/member.name
        path.write_bytes(archive.extractfile(member).read())
(target/'config.yaml').write_text(new)
print('Nook Casa aggiornato a 0.4.3; credenziali conservate.')
print('Backup precedente: '+str(backup))
NOOK_UPDATE_PY
